import { Component, EventEmitter, Output, inject } from '@angular/core';

import { DIALOG_DATA } from '@angular/cdk/dialog';
import { FormsModule } from '@angular/forms';
import { DialogEvent } from '../common/types';
import { DialogCloseDirective } from '../ui/controls/dialog';
import { SpinnerComponent } from '../ui/controls/spinner.component';
import { ItemSearchFieldComponent } from '../ui/custom-fields/item-search-field.component';
import { IconComponent } from '../ui/icon.component';
import { TranslatePipe } from '../ui/translate.pipe';

export interface SelectItemModalData<T = unknown> {
    service_name: string;
    query_fn: (query: string) => Promise<T[]>;
}

@Component({
    selector: 'select-item-modal',
    template: `
        <div
            class="bg-base-200 mx-2 mt-2 flex items-center justify-between rounded-sm px-4 py-2"
        >
            <h3 class="text-xl font-medium">
                {{ 'COMMON.ITEM_ADD' | translate: { item: name } }}
            </h3>
            @if (!loading) {
                <button
                    icon
                    ripple
                    appDialogClose
                    [attr.aria-label]="'COMMON.CLOSE' | translate"
                >
                    <icon>close</icon>
                </button>
            }
        </div>
        @if (!loading) {
            <main class="h-[65vh] w-lg max-w-[calc(100vw-2rem)] px-2 pt-2">
                <item-search-field
                    class="block h-full"
                    [query_fn]="$any(query_fn)"
                    [exclude]="filter_fn"
                    [(ngModel)]="item"
                    [display_list]="true"
                />
            </main>
        } @else {
            <main
                class="flex w-full flex-col items-center justify-center p-16 opacity-30"
            >
                <div class="icon">
                    <app-spinner diameter="32" />
                </div>
                <div class="text">
                    {{ 'COMMON.PROCESSING_REQUEST' | translate }}
                </div>
            </main>
        }
        @if (!loading) {
            <footer class="border-base-200 flex justify-end border-t px-4 py-2">
                <button
                    btn
                    ripple
                    type="submit"
                    (click)="submit()"
                    [disabled]="!item"
                >
                    {{ 'COMMON.ITEM_ADD_SELECTED' | translate }}
                </button>
            </footer>
        }
    `,
    styles: [``],
    imports: [
        DialogCloseDirective,
        SpinnerComponent,
        TranslatePipe,
        ItemSearchFieldComponent,
        FormsModule,
        IconComponent,
    ],
})
export class SelectItemModalComponent {
    private _data = inject<SelectItemModalData>(DIALOG_DATA);

    /** Emitter for user action on the modal */
    @Output() public event = new EventEmitter<DialogEvent>();
    /** Item to edit */
    public item: unknown;
    /** Whether the item request is being processed */
    public loading: boolean;

    public readonly filter_fn = () => false;

    public get query_fn(): (query: string) => Promise<unknown[]> {
        return this._data.query_fn;
    }

    public get name(): string {
        return this._data.service_name;
    }

    public submit() {
        this.loading = true;
        this.event.emit({ reason: 'action', metadata: this.item });
    }
}
